<script>document.addEventListener('DOMContentLoaded',()=>{const b=document.getElementById('fis-satirlar'),t=document.getElementById('fis-toplam');let i=1,m=n=>'₺'+Number(n||0).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2});function c(){let s=0;b.querySelectorAll('.fis-satir').forEach(r=>{let d=+r.querySelector('.dahil').value||0,o=+r.querySelector('.oran').value||0,h=d/(1+o/100);r.querySelector('.haric').textContent=m(h);r.querySelector('.kdv').textContent=m(d-h);s+=d});t.textContent=m(s)}function bind(r){r.querySelectorAll('.dahil,.oran').forEach(x=>x.addEventListener('input',c));r.querySelector('.sil').addEventListener('click',()=>{if(b.children.length>1){r.remove();c()}})}bind(b.firstElementChild);document.getElementById('satir-ekle').addEventListener('click',()=>{let r=b.firstElementChild.cloneNode(true);r.querySelectorAll('input,select').forEach(x=>{x.name=x.name.replace(/\[\d+\]/,'['+i+']');if(x.tagName==='SELECT')x.value=20;else x.value=''});r.querySelector('.haric').textContent=r.querySelector('.kdv').textContent='₺0,00';b.appendChild(r);bind(r);i++})})</script>
